mapper.select:
SELECT (SELECT COUNT(*) FROM user_account
         WHERE (CAST(#{userId} AS uuid) IS NULL OR id = #{userId})) AS registered_accounts,
       (SELECT COUNT(*) FROM user_account
         WHERE created_at >= #{period.fromInclusive}
           AND created_at < #{period.toExclusive}
           AND (CAST(#{userId} AS uuid) IS NULL OR id = #{userId})) AS new_accounts
